const formsComponentBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE &&
  items.every((item) => item.type === items[0].type);

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const policyBasePremium = (items: Item[]): number =>
  formsComponentBlock(items)
    ? BLOCK_BASE_PREMIUM
    : sumOfItemBasePremiums(items);
